import numpy as np

grid = np.array([
    [0,"X","X",10,"X",42,44,46,48],
    [1,2,"X",8,"X",40,"X",47,50],
    ["X",3,5,7,"X",34,"X",49,51],
    [6,4,"X",9,"X",29,25,"X","X"],
    ["X","X","X",11,12,"X",21,"X",39],
    [45,43,41,"X",13,15,18,"X",33],
    ["X","X",35,"X",14,17,20,24,28],
    ["X",36,30,"X",16,"X",23,"X","X"],
    [37,31,26,22,19,"X",27,32,38]
])

# Convert the grid to a dictionary
grid_dict = {}
for i in range(grid.shape[0]):
    for j in range(grid.shape[1]):
        if grid[i, j] != 'X':
            state = (i, j)
            if state not in grid_dict:
                grid_dict[state] = []
            # Check all four directions
            if i > 0 and grid[i-1, j] != 'X' and (i-1, j) != state:
                grid_dict[state].append((i-1, j))
            if i < grid.shape[0] - 1 and grid[i+1, j] != 'X' and (i+1, j) != state:
                grid_dict[state].append((i+1, j))
            if j > 0 and grid[i, j-1] != 'X' and (i, j-1) != state:
                grid_dict[state].append((i, j-1))
            if j < grid.shape[1] - 1 and grid[i, j+1] != 'X' and (i, j+1) != state:
                grid_dict[state].append((i, j+1))

# Create the adjacency list
adj_list = []
for key in grid_dict:
    adj_list.append([key, grid_dict[key]])

print(adj_list)
